<h2>Crear cuenta</h2><form method="post" action="index.php?route=register_process">
<div class="form-group"><label>Nombre completo</label><input class="form-control" name="full_name" maxlength="100" required></div><div class="form-group"><label>Usuario</label><input class="form-control" name="username" maxlength="50" required></div><div class="form-group"><label>Correo</label><input class="form-control" type="email" name="email" required></div><div class="form-group"><label>Contraseña</label><input class="form-control" type="password" name="password" required></div><button class="btn btn-primary">Registrarse</button> <a class="btn btn-secondary" href="index.php?route=login">Cancelar</a></form>
